// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address currentOwner, address newOwner) public {
        vm.assume(currentOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(currentOwner != newOwner);

        // Set the current owner to be the one fuzzed
        vm.prank(address(this));
        c.transferOwnership(currentOwner);

        // Now call transferOwnership as the current owner to change to newOwner
        vm.prank(currentOwner);
        c.transferOwnership(newOwner);

        // Assert that the owner is now newOwner
        assertTrue(c.owner() == newOwner);
    }
}

